@startuml

class RepairShop {
  + Name : string
  + Address : string
}

class Repair {
  + Duration : int
  + Cost : double
}

class Vehicle {
  + LicensePlateNumber : string
  + Mileage : int
  + Type : VehicleType
}

class Order {
  + PacketSize : int
  + Comment : string
  + StartTime : time
  + EndTime : time
  + PickUpAddress : string
  + DeliveryAddress : string
}

abstract class Employee {
  + Name : string
  + Ssn : int
  + Username : string
  + Password : string
}

class Driver extends Employee {}

class AdministrationEmployee extends Employee {
  + FieldOfActivity : string
}

class Customer {
  + Name : string
  + BillingAddress : string
}

class PartnerCompany {
  + Name : string
  + Address : string
}

enum VehicleType {
  RefrigeratedTruck
  SmallVan
  LoadingPlatform
  BoxTruck
}

RepairShop "1" -- "*" Repair
Repair "*" -- "1" Vehicle
Repair "*" -- "1" Employee
Vehicle "1" -- "*" Order
Driver "1" -- "*" Order
AdministrationEmployee "0..1" -- "*" Order
Order "*" -- "1" Customer
Order "*" -- "1" Vehicle
Order "*" -- "1" AdministrationEmployee : assigned by
Order "*" -- "1" PartnerCompany
Order "*" -- "1" Driver : completed by

@enduml

